/* HRM › Recruitment › Recruitments (J1, J2, J4, S2) and Talent pool (T1, T2). */
(function () {
  const { S, esc, acts, ins, chs } = App; const H = App.H;
  const rf = App.ui.recf = { q: '', mgr: 'All', status: 'All', pub: 'Any', sel: [] };
  const ST = { Open: ['t-green', 'ri-checkbox-blank-circle-fill'], 'Closing soon': ['t-orange', 'ri-time-line'], Closed: ['t-grey', 'ri-lock-line'], Draft: ['t-grey', 'ri-draft-line'], Completed: ['t-blue', 'ri-checkbox-circle-line'] };
  const stChip = r => `<span class="chip sm filled ${ST[r.status][0]}"><i class="${ST[r.status][1]}" ${r.status === 'Open' ? 'style="font-size:8px"' : ''}></i>${r.status}</span>`;
  const list = () => S.recruitments.filter(r => (rf.mgr === 'All' || r.managers.includes(rf.mgr)) && (rf.status === 'All' || r.status === rf.status) && (rf.pub === 'Any' || (rf.pub === 'Published') === r.published) && (!rf.q || r.title.toLowerCase().includes(rf.q.toLowerCase())));

  H.route('/hrm/recruitments', () => H.frame({ tab: 'recruitments', primary: `<button class="btn primary lg" data-act="rec-new"><i class="ri-add-circle-line"></i>New recruitment</button>`, title: 'Recruitments', sub: 'Create and manage job openings, their managers, vacancies and publishing.',
    actions: `<button class="btn outlined lg" data-act="rec-actions" data-menu-anchor aria-haspopup="menu"><i class="ri-settings-3-line"></i>Actions</button>`,
    body: `<div class="hbody stack g16"><div class="filters">${App.field('Search', `<input data-in="rec-q" value="${esc(rf.q)}" placeholder="Search recruitments">`, { cls: 'search' })}${App.select('Managers', 'rec-mgr', [{ v: 'All', t: 'All managers' }, ...S.staff.filter(s => s.id !== 'ma').map(s => ({ v: s.id, t: s.name }))], rf.mgr)}${App.select('Status', 'rec-status', [{ v: 'All', t: 'All Status' }, ...Object.keys(ST)], rf.status)}${App.select('Published', 'rec-pub', ['Any', 'Published', 'Not published'], rf.pub)}<button class="clear-btn" data-act="rec-clear"><i class="ri-close-line"></i>Clear filters</button></div>
      <div id="rec-table">${S.hrmFail ? failed() : table()}</div></div>` }));
  const failed = () => `<div class="empty-box"><div class="empty"><span class="ic red"><i class="ri-error-warning-line"></i></span><h2 class="sub2" style="font-size:18px;font-weight:400">We couldn’t load recruitments</h2><p>Something went wrong on our side. Your data is safe — please try again in a moment.</p><div class="row g12"><button class="btn outlined lg" data-act="soon" data-what="Contact support">Contact support</button><button class="btn primary lg" data-act="rec-retry"><i class="ri-refresh-line"></i>Try again</button></div></div></div>`;
  function table() { const l = list();
    return `<div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th style="width:48px"><label class="cbx"><input type="checkbox" data-ch="rec-all" ${l.length && l.every(r => rf.sel.includes(r.id)) ? 'checked' : ''} aria-label="Select all"></label></th><th>Recruitment</th><th>Managers</th><th>Vacancies</th><th>Candidates</th><th>Hired</th><th>Dates</th><th>Status</th><th>Published</th><th style="text-align:right">Actions</th></tr></thead><tbody>
      ${l.length ? l.map(r => { const n = S.candidates.filter(c => c.rid === r.id).length; return `<tr class="click" data-act="rec-view" data-id="${r.id}"><td><label class="cbx"><input type="checkbox" data-ch="rec-sel" data-id="${r.id}" ${rf.sel.includes(r.id) ? 'checked' : ''} aria-label="Select ${esc(r.title)}"></label></td>
        <td class="cell2"><span>${esc(r.title)}</span><small>${esc(r.type)} · ${esc(r.location)}</small></td><td>${H.avs(r.managers)}</td><td class="tnum">${r.vacancies}</td><td class="tnum">${n}</td><td><span class="row g8">${H.prog(r.hired, r.vacancies)}<span class="caption tnum">${r.hired} / ${r.vacancies}</span></span></td><td>${esc(r.start.slice(0, 6))} – ${esc(r.end || '—')}</td><td>${stChip(r)}</td>
        <td>${App.sw(r.published, `data-ch="rec-pubsw" data-id="${r.id}" ${r.status === 'Draft' || r.status === 'Closed' ? '' : ''}`, `Published on career page: ${r.title}`)}</td>
        <td style="text-align:right"><span class="row-actions"><button class="icon-btn s20" data-act="rec-view" data-id="${r.id}" aria-label="View ${esc(r.title)}"><i class="ri-eye-line"></i></button><button class="icon-btn s20" data-act="rec-edit" data-id="${r.id}" aria-label="Edit ${esc(r.title)}"><i class="ri-pencil-line"></i></button><button class="icon-btn s20" data-act="rec-dup" data-id="${r.id}" aria-label="Duplicate ${esc(r.title)}"><i class="ri-file-copy-line"></i></button><button class="icon-btn s20" data-act="rec-share" data-id="${r.id}" aria-label="Share ${esc(r.title)}"><i class="ri-share-line"></i></button><button class="icon-btn s20" data-act="rec-close" data-id="${r.id}" aria-label="${r.status === 'Closed' ? 'Reopen' : 'Close'} ${esc(r.title)}"><i class="ri-archive-line"></i></button><button class="icon-btn s20 danger" data-act="rec-del" data-id="${r.id}" aria-label="Delete ${esc(r.title)}"><i class="ri-delete-bin-line"></i></button></span></td></tr>`; }).join('')
      : `<tr class="empty-row"><td colspan="10">No recruitments match. <button class="btn text brand sm" data-act="rec-clear">Clear filters</button></td></tr>`}</tbody></table></div><div class="pager"><span>Rows per page: 10</span><span class="tnum">1–${l.length} of ${l.length}</span><span class="row g4"><button class="icon-btn s20" disabled aria-label="Previous page"><i class="ri-arrow-left-s-line"></i></button><button class="icon-btn s20" disabled aria-label="Next page"><i class="ri-arrow-right-s-line"></i></button></span></div></div>`; }
  const redraw = () => { const t = App.$('#rec-table'); if (t) t.innerHTML = S.hrmFail ? failed() : table(); };
  ins['rec-q'] = el => { rf.q = el.value; redraw(); }; chs['rec-mgr'] = el => { rf.mgr = el.value; redraw(); }; chs['rec-status'] = el => { rf.status = el.value; redraw(); }; chs['rec-pub'] = el => { rf.pub = el.value; redraw(); };
  acts['rec-clear'] = () => { Object.assign(rf, { q: '', mgr: 'All', status: 'All', pub: 'Any' }); App.render(); };
  chs['rec-sel'] = el => { rf.sel = el.checked ? [...rf.sel, el.dataset.id] : rf.sel.filter(x => x !== el.dataset.id); };
  chs['rec-all'] = el => { rf.sel = el.checked ? list().map(r => r.id) : []; redraw(); };
  chs['rec-pubsw'] = el => { const r = H.rec(el.dataset.id); if (el.checked && (r.status === 'Draft' || r.status === 'Closed')) r.status = 'Open'; r.published = el.checked; redraw(); App.snack(el.checked ? `“${r.title}” is live on your career page.` : `“${r.title}” hidden from your career page.`, 'info'); };
  acts['rec-retry'] = () => { S.hrmFail = false; App.render(); App.snack('Recruitments loaded.'); };
  acts['rec-actions'] = el => App.menu(el, `<button data-pick="export"><i class="ri-download-2-line"></i>Export <span class="caption" style="margin-left:auto">CSV</span></button><button data-pick="close" ${rf.sel.length ? '' : 'disabled'}><i class="ri-archive-line"></i>Close selected</button><hr><button data-pick="fail"><i class="ri-error-warning-line"></i>Simulate a loading error</button>`, v => {
    if (v === 'export') App.snack('Recruitments exported as CSV.', 'info'); if (v === 'close') { rf.sel.forEach(id => { const r = H.rec(id); r.status = 'Closed'; r.published = false; }); App.snack(`${rf.sel.length} recruitments closed.`); rf.sel = []; redraw(); }
    if (v === 'fail') { S.hrmFail = true; App.render(); } }, { width: 280 });
  acts['rec-edit'] = el => H.openRecruitment(el.dataset.id);
  acts['rec-dup'] = el => { const r = H.rec(el.dataset.id); const copy = Object.assign({}, r, { id: 'r' + Date.now(), title: r.title + ' (copy)', status: 'Draft', published: false, hired: 0, managers: [...r.managers], skills: [...r.skills], reqs: [...r.reqs] }); S.recruitments.splice(S.recruitments.indexOf(r) + 1, 0, copy); redraw(); App.snack(`Duplicated as a draft — “${copy.title}”.`, 'success', { label: 'Edit', fn: () => H.openRecruitment(copy.id) }); };
  acts['rec-share'] = el => { const r = H.rec(el.dataset.id); if (!r.published) { App.snack('Publish it to your career page first, then share the link.', 'info'); return; } try { navigator.clipboard.writeText(`https://careers.leafease.com/${S.career.slug}/${r.id}`)?.catch?.(() => {}); } catch (e) {} App.snack('Job link copied to clipboard.', 'info'); };
  acts['rec-close'] = el => { const r = H.rec(el.dataset.id); const prev = [r.status, r.published]; r.status = r.status === 'Closed' ? 'Open' : 'Closed'; r.published = r.status === 'Open'; redraw(); App.snack(r.status === 'Closed' ? `“${r.title}” closed — no new applications.` : `“${r.title}” reopened.`, 'success', { label: 'Undo', fn: () => { [r.status, r.published] = prev; redraw(); } }); };

  /* details modal (J2) */
  acts['rec-view'] = el => { const r = H.rec(el.dataset.id); const n = S.candidates.filter(c => c.rid === r.id).length;
    App.dialog(`<div class="dlg-head"><div class="stack g4"><div class="row g8 wrap"><h2 id="dlg-title" class="h6" style="font-size:20px">${esc(r.title)}</h2>${stChip(r)}${r.published ? App.chip('Published', 't-teal', 'sm filled') : App.chip('Not published', 't-grey', 'sm filled')}</div><span class="body2 muted">${esc(r.type)} · ${esc(r.location)} · QA Riverside Private Clinic</span></div><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>
      <div class="dlg-body"><div class="mini-facts plain">${[['Vacancies', r.vacancies], ['Candidates', n], ['Hired', `${r.hired} of ${r.vacancies}`], ['Days left', r.closesIn]].map(([k, v]) => `<div><span class="cell2"><small>${k}</small><b style="font-size:18px;font-weight:500">${v}</b></span></div>`).join('')}</div>
        <div class="stack g4"><span class="overline">Description</span><p class="body2" style="margin:0">${esc(r.desc)}</p></div>
        <div class="g2"><div class="stack g4"><span class="overline">Managers</span><div class="row g8 wrap">${r.managers.map(m => App.chip(H.staff(m).name, 't-teal', 'sm filled')).join('')}</div></div><div class="stack g4"><span class="overline">Employment type</span><span>${esc(r.type)}</span></div>
          <div class="stack g4"><span class="overline">Start date</span><span>${esc(r.start)}</span></div><div class="stack g4"><span class="overline">End date</span><span>${esc(r.end || '—')}</span></div>
          <div class="stack g4"><span class="overline">Skills</span><div class="row g8 wrap">${r.skills.slice(0, 1).map(s => App.chip(s, 't-teal', 'sm filled')).join('')}${r.skills.length > 1 ? App.chip('+' + (r.skills.length - 1), 't-teal', 'sm filled') : ''}${r.skills.length ? '' : '<span class="muted">—</span>'}</div></div><div class="stack g4"><span class="overline">Application survey</span><span>${esc(S.surveys.find(s => s.id === r.survey)?.name || 'None')}</span></div></div>
        <div class="settings-chips"><b>Settings</b>${[[r.status !== 'Closed', 'Active'], [r.published, 'Public'], [true, r.photo ? 'Profile photo requested' : 'Profile photo optional'], [true, r.resumeOptional ? 'Resume optional' : 'Resume required']].map(([on, t]) => `<span class="chip sm">${on && /Active|Public/.test(t) ? '<i class="ri-check-line"></i>' : ''}${t}</span>`).join('')}</div></div>
      <div class="dlg-foot"><span class="note">Created ${esc(r.created || '05 Oct 2026')} by Muhammad Arslan · Updated today</span><button class="btn outlined lg" data-act="rec-edit" data-id="${r.id}"><i class="ri-pencil-line"></i>Edit</button><button class="btn primary lg" data-act="rec-pipe" data-id="${r.id}" ${r.status === 'Draft' ? 'disabled' : ''}><i class="ri-arrow-right-up-line"></i>Open pipeline</button></div>`, { width: 680 }); };
  acts['rec-pipe'] = el => { App.ui.hrmRec = el.dataset.id; App.closeModal(); App.go('#/hrm/pipeline'); };

  /* delete (J4) */
  H.deleteRec = rid => { const r = H.rec(rid); const n = S.candidates.filter(c => c.rid === rid).length;
    App.dialog(`<div class="dlg-head"><div class="row g12 top"><span class="icon-circle sq"><i class="ri-delete-bin-line"></i></span><div class="stack"><h2 id="dlg-title" class="h6" style="font-size:18px">Delete “${esc(r.title)}”?</h2><span class="body2">This can’t be undone.</span></div></div><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>
      <div class="dlg-body"><div class="al"><i class="ri-error-warning-line"></i><div class="txt">Its stages, survey link and career page listing will be removed.${n ? ` ${n} candidate${n > 1 ? 's are' : ' is'} kept and moved to “Unassigned”.` : ''}</div></div>
        ${r.status !== 'Closed' ? `<div class="hint-box"><i class="ri-archive-line"></i><span>Only want to stop applications? Close the recruitment instead — you can reopen it later.</span></div>` : ''}${H.typeConfirm(r.title, 'rec')}</div>
      <div class="dlg-foot">${r.status !== 'Closed' ? `<button class="btn outlined lg" data-act="rec-close-instead" data-id="${r.id}">Close instead</button>` : `<button class="btn outlined lg" data-act="close-modal">Cancel</button>`}<button class="btn danger lg" data-act="rec-del-go" data-id="${r.id}" data-confirm-btn disabled><i class="ri-delete-bin-line"></i>Delete recruitment</button></div>`, { width: 480 }); };
  acts['rec-del'] = el => H.deleteRec(el.dataset.id);
  acts['rec-close-instead'] = el => { const r = H.rec(el.dataset.id); r.status = 'Closed'; r.published = false; App.closeModal(); App.render(); App.snack(`“${r.title}” closed instead — you can reopen it any time.`); };
  acts['rec-del-go'] = el => { const r = H.rec(el.dataset.id); S.recruitments = S.recruitments.filter(x => x !== r); S.candidates.filter(c => c.rid === r.id).forEach(c => { c.stage = 'unassigned'; c.rid = S.recruitments[0]?.id || null; }); if (App.ui.hrmRec === r.id) App.ui.hrmRec = null;
    App.closeModal(); App.render(); App.snack(`“${r.title}” deleted.`); };

  /* ---------- Talent pool (T1, T2) ---------- */
  const tp = App.ui.tp = { q: '', banner: true };
  H.route('/hrm/talent-pool', () => { const inPool = S.candidates.filter(c => c.pools.length); const match = S.candidates.filter(c => c.match && c.pools.length);
    return H.frame({ tab: 'talent-pool', primary: `<button class="btn primary lg" data-act="pool-new"><i class="ri-add-circle-line"></i>Create pool</button>`, title: 'Talent pool', sub: 'Strong past applicants, grouped into pools so you can re-engage them for new roles.',
      actions: `<button class="btn outlined lg" data-act="soon" data-what="Talent pool filters"><i class="ri-filter-3-line"></i>Filter</button>`,
      body: `<div class="hbody stack g16">${tp.banner && match.length ? `<div class="ai-banner"><span class="ai-ic"><i class="ri-sparkling-2-line"></i></span><div class="grow cell2"><b class="brand" style="font-weight:500">${match.length + 1} people in your talent pool match “Clinical Pharmacist”</b><small>Matched on experience and skills from their CVs and past interview feedback.</small></div><button class="btn primary sm" data-act="tp-review">Review matches</button><button class="icon-btn s20" data-act="tp-dismiss" aria-label="Dismiss"><i class="ri-close-line"></i></button></div>` : ''}
        <div class="row between wrap g12"><span class="body2">${S.pools.length} pools · ${inPool.length} candidates</span><div style="width:min(300px,100%)">${App.field('Search', `<span class="adorn"><i class="ri-search-line"></i></span><input data-in="tp-q" value="${esc(tp.q)}" placeholder="Search candidates in pool…">`, { cls: 'sm' })}</div></div>
        <div id="pools" class="stack g16">${pools()}</div></div>` }); });
  function pools() { return S.pools.map(p => { const cs = S.candidates.filter(c => c.pools.includes(p.id) && (!tp.q || H.name(c).toLowerCase().includes(tp.q.toLowerCase())));
    return `<section class="pool-card ${p.open ? 'open' : ''}"><div class="pool-h"><span class="fic"><i class="ri-heart-3-line"></i></span><div class="grow cell2"><span class="row g8"><b style="font-size:16px;font-weight:600">${esc(p.name)}</b><span class="count">${cs.length}</span>${p.auto ? App.chip('Auto-add on', 't-purple', 'sm filled') : ''}</span><small>${esc(p.desc)}</small></div>
      <button class="btn text brand" data-act="pool-add" data-id="${p.id}"><i class="ri-user-add-line"></i>Add candidate</button><button class="icon-btn s20" data-act="pool-menu" data-id="${p.id}" data-menu-anchor aria-label="Pool options"><i class="ri-more-2-fill"></i></button><button class="icon-btn s20" data-act="pool-tog" data-id="${p.id}" aria-expanded="${p.open}" aria-label="${p.open ? 'Collapse' : 'Expand'} ${esc(p.name)}"><i class="${p.open ? 'ri-arrow-up-s-line' : 'ri-arrow-down-s-line'}"></i></button></div>
      ${p.open ? (cs.length ? `<div class="pool-b"><div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th>Candidate</th><th>From recruitment</th><th>Reason</th><th>Rating</th><th>Added</th><th>Resume</th><th>Actions</th></tr></thead><tbody>${cs.map(c => `<tr><td><span class="person">${H.cav(c, 'sm')}<span class="cell2"><span class="row g8"><a class="plain" href="#/hrm/candidates/${c.id}">${esc(H.name(c))}</a>${c.match ? '<span class="chip sm filled t-teal"><i class="ri-sparkling-2-line"></i>Match</span>' : ''}</span><small>${esc(c.email)}</small></span></span></td><td>${esc(H.rec(c.rid)?.title || '—')}</td><td>${App.chip(c.poolReason || 'Added manually', 't-grey', 'sm filled')}</td><td>${H.starsHTML(c.rating, 'xs')}</td><td>${esc(c.poolAdded || '—')}</td><td><button class="linkish" data-act="cv-view" data-id="${c.id}"><i class="ri-file-text-line"></i> View</button></td>
        <td><span class="row g8"><button class="btn outlined sm" data-act="tp-move" data-id="${c.id}" data-menu-anchor><i class="ri-arrow-right-up-line"></i>Move to recruitment</button><button class="icon-btn s20 danger" data-act="tp-remove" data-id="${c.id}" data-p="${p.id}" aria-label="Remove ${esc(H.name(c))} from pool"><i class="ri-delete-bin-line"></i></button></span></td></tr>`).join('')}</tbody></table></div></div></div>`
        : `<div class="empty" style="padding:32px 16px"><i class="ri-team-line" style="font-size:24px"></i><b style="font-weight:500">No candidates in this pool yet</b><p class="caption">Add candidates from the pipeline or candidate profile using “Add to talent pool”.</p></div>`) : ''}</section>`; }).join(''); }
  ins['tp-q'] = el => { tp.q = el.value; App.$('#pools').innerHTML = pools(); };
  acts['tp-dismiss'] = () => { tp.banner = false; App.render(); };
  acts['tp-review'] = () => { S.pools[0].open = true; tp.q = ''; App.render(); App.snack('Matches are tagged “Match” below.', 'info'); };
  acts['pool-tog'] = el => { const p = S.pools.find(x => x.id === el.dataset.id); p.open = !p.open; App.$('#pools').innerHTML = pools(); };
  acts['pool-add'] = el => { const p = S.pools.find(x => x.id === el.dataset.id); const opts = S.candidates.filter(c => !c.pools.includes(p.id));
    App.menu(el, `<div class="msearch">${App.field('', '<input placeholder="Search candidates…" aria-label="Search candidates">', { cls: 'sm' })}</div><div class="mlist">${opts.map(c => `<button data-pick="${c.id}">${H.cav(c, 'sm')}<span class="two"><span>${esc(H.name(c))}</span><small>${esc(H.rec(c.rid)?.title || '')}</small></span></button>`).join('')}</div>`,
      v => { const c = H.cand(v); c.pools.push(p.id); c.poolReason = 'Added manually'; c.poolAdded = '08 Oct 2026'; p.open = true; App.render(); App.snack(`${H.name(c)} added to “${p.name}”.`); },
      { width: 300, onSearch: (q, m) => m.querySelectorAll('.mlist button').forEach(b => { b.hidden = !b.textContent.toLowerCase().includes(q.toLowerCase()); }) }); };
  acts['pool-menu'] = el => { const p = S.pools.find(x => x.id === el.dataset.id);
    App.menu(el, `<button data-pick="email"><i class="ri-mail-line"></i>Email everyone in pool</button><button data-pick="rename"><i class="ri-pencil-line"></i>Edit pool</button><hr><button class="danger" data-pick="del"><i class="ri-delete-bin-line"></i>Delete pool</button>`, v => {
      if (v === 'email') App.snack(`Drafting an email to ${S.candidates.filter(c => c.pools.includes(p.id)).length} candidates.`, 'info'); if (v === 'rename') poolModal(p);
      if (v === 'del') { const i = S.pools.indexOf(p); S.pools.splice(i, 1); S.candidates.forEach(c => { c.pools = c.pools.filter(x => x !== p.id); }); App.render(); App.snack(`Pool “${p.name}” deleted. Candidates stay in Candidates.`); } }, { width: 260 }); };
  acts['tp-move'] = el => { const c = H.cand(el.dataset.id);
    App.menu(el, `<div class="label">Move ${esc(c.first)} to</div>${S.recruitments.filter(r => r.status === 'Open' || r.status === 'Closing soon').map(r => `<button data-pick="${r.id}">${esc(r.title)}</button>`).join('')}`, v => {
      const r = H.rec(v); c.rid = v; c.stage = 'applied'; c.status = 'progress'; delete c.rejected; c.when = 'Just now'; App.render(); App.snack(`${H.name(c)} added to ${r.title} at Applied.`, 'success', { label: 'Open pipeline', fn: () => { App.ui.hrmRec = v; App.go('#/hrm/pipeline'); } }); }, { width: 260 }); };
  acts['tp-remove'] = el => { const c = H.cand(el.dataset.id); const pid = el.dataset.p; c.pools = c.pools.filter(x => x !== pid); App.$('#pools').innerHTML = pools(); App.snack(`${H.name(c)} removed from the pool.`, 'success', { label: 'Undo', fn: () => { c.pools.push(pid); App.$('#pools') && (App.$('#pools').innerHTML = pools()); } }); };

  let pd = null;
  acts['pool-new'] = () => poolModal(null);
  function poolModal(p) { pd = p ? { id: p.id, name: p.name, desc: p.desc, auto: p.auto, from: p.from || 'r5', tried: false } : { id: null, name: '', desc: '', auto: true, from: 'r5', tried: false }; drawPool(); }
  function drawPool() { const e = k => pd.tried && !pd[k].trim(); const r = H.rec(pd.from);
    App.dialog(`<div class="dlg-head"><div class="stack g4"><h2 id="dlg-title" class="h6" style="font-size:20px">${pd.id ? 'Edit talent pool' : 'Create talent pool'}</h2><p class="body2 muted" style="margin:0">Group candidates you’d like to re-engage later.</p></div><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>
      <div class="dlg-body">${App.field('Pool name', `<input data-in="pd" data-k="name" value="${esc(pd.name)}" placeholder="e.g. Clinical Pharmacist — shortlist">`, { req: true, cls: e('name') ? 'err' : '' })}
        <div class="stack g4">${App.field('Description', `<textarea rows="2" maxlength="300" data-in="pd" data-k="desc" placeholder="Who belongs here">${esc(pd.desc)}</textarea>`, { req: true, cls: 'multi ' + (e('desc') ? 'err' : '') })}<p class="helper">Character limit: 300</p></div>
        ${App.field('Company', '<input value="QA Riverside Private Clinic" disabled>', { cls: 'dis filled-dis' })}
        <div class="toggle-card bordered"><div><b>Auto-add rejected candidates</b><span class="caption">When rejected with “Vacancy filled” from ${`<select class="inline-sel" data-ch="pd-from" aria-label="From recruitment">${S.recruitments.map(x => `<option value="${x.id}" ${x.id === pd.from ? 'selected' : ''}>${esc(x.title)}</option>`).join('')}</select>`}</span></div>${App.sw(pd.auto, 'data-ch="pd-auto"', 'Auto-add rejected candidates')}</div></div>
      <div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="pd-go">${pd.id ? 'Save' : 'Create pool'}</button></div>`, { width: 600 }); }
  ins.pd = el => { pd[el.dataset.k] = el.value; }; chs['pd-auto'] = el => { pd.auto = el.checked; }; chs['pd-from'] = el => { pd.from = el.value; };
  acts['pd-go'] = () => { if (!pd.name.trim() || !pd.desc.trim()) { pd.tried = true; drawPool(); return; }
    const p = S.pools.find(x => x.id === pd.id); if (p) Object.assign(p, { name: pd.name.trim(), desc: pd.desc.trim(), auto: pd.auto, from: pd.from }); else S.pools.unshift({ id: 'p' + Date.now(), name: pd.name.trim(), desc: pd.desc.trim(), auto: pd.auto, from: pd.from, open: true });
    App.closeModal(); App.render(); App.snack(pd.id ? 'Pool updated.' : `Pool “${pd.name.trim()}” created.`); };
})();
